function toast(t='Saved ✓'){let e=document.querySelector('.wr19-toast');if(!e){e=document.createElement('div');e.className='wr19-toast';document.body.appendChild(e)}e.textContent=t;e.classList.add('show');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),1500)}
async function uid(){const{data}=await supabase.auth.getUser();return data?.user?.id||null}
const roots=()=>S.cargo.filter(x=>!x.parent_id),children=id=>S.cargo.filter(x=>x.parent_id===id),party=r=>S.parties.find(x=>String(x.role||'').toLowerCase()===r),ent=id=>S.entities.find(x=>x.id===id);
const packageTypes=()=>{const custom=(S.options||[]).filter(x=>x.option_group==='PACKAGE_TYPE'&&x.active).map(x=>[x.code,x.uom||x.code]);const map=new Map([...BUILTIN_TYPES,...custom].map(x=>[x[0],x]));return [...map.values()]};
const customerName=()=>ent(S.job?.customer_id)?.name||'Unidentified customer';
const steps=()=>[...(S.workflow?.steps||FALLBACK)].filter(x=>x.enabled!==false).sort((a,b)=>(a.order||0)-(b.order||0));
const skipped=k=>S.events.some(e=>e.event_type==='STEP_SKIPPED'&&e.event_data?.step_key===k);
function done(s){const v=S.visit||{},r=roots();switch(s.key){case'check_in':return!!v.time_in;case'verify_driver':return!!v.driver_id_verified;case'start_unload':return!!v.operation_started_at;case'finish_unload':return!!v.operation_completed_at;case'release_driver':return!!v.time_out;case'parties':return!!S.job?.customer_id&&!!party('shipper')&&!!party('consignee');case'receive_cargo':return r.length>0&&r.every(x=>x.processing_status==='processed');case'documents':return S.docs.length>0||skipped(s.key);case'compliance':return S.controls.length===0||S.controls.every(x=>x.verified||['complete','cleared','released'].includes(String(x.status||'').toLowerCase()))||skipped(s.key);case'putaway':return r.length>0&&r.every(x=>x.current_location_id||x.warehouse_location_id);case'complete':return!!S.wr.completed_at;case'notify_customer':return S.events.some(e=>e.event_type==='CUSTOMER_NOTIFIED')||skipped(s.key);default:return S.events.some(e=>e.event_type==='STEP_COMPLETED'&&e.event_data?.step_key===s.key)||skipped(s.key)}}
const current=()=>steps().find(x=>!done(x))||steps().at(-1);
function missing(){const m=[];if(!S.job?.customer_id)m.push('Customer');if(!party('shipper'))m.push('Shipper');if(!party('consignee'))m.push('Consignee');if(!roots().length)m.push('Cargo');if(S.visit?.time_in&&!S.visit?.time_out)m.push('Driver on site');if(roots().some(x=>!(x.current_location_id||x.warehouse_location_id)))m.push('Put-away');if(S.flags.length)m.push(`${S.flags.length} exception${S.flags.length===1?'':'s'}`);if(S.controls.some(x=>!x.verified&&!['complete','cleared','released'].includes(String(x.status||'').toLowerCase())))m.push('Compliance');return m}
function summary(){const r=roots();return{expected:S.visit?.unload_expected_qty,unloaded:S.visit?.unload_actual_qty,processed:r.filter(x=>x.processing_status==='processed').reduce((a,x)=>a+Number(x.quantity||0),0),putaway:r.filter(x=>x.current_location_id||x.warehouse_location_id).reduce((a,x)=>a+Number(x.quantity||0),0),exceptions:S.flags.length,missing:missing().length}}
function completion(){const x=steps(),n=x.filter(done).length;return{x,n,pct:x.length?Math.round(n/x.length*100):0}}
async function addEvent(type,data={}){await supabase.from('workflow_events').insert({organization_id:S.wr.organization_id,job_id:S.wr.job_id,warehouse_receipt_id:S.wr.id,event_type:type,event_data:data,actor_id:await uid()})}

async function load(id){const{data:wr,error}=await supabase.from('warehouse_receipts').select('*').eq('id',id).single();if(error)throw error;const q=[
 supabase.from('jobs').select('*').eq('id',wr.job_id).maybeSingle(),supabase.from('warehouse_visits').select('*').eq('warehouse_receipt_id',id).eq('direction','inbound').order('created_at',{ascending:false}).limit(1),supabase.from('cargo_units').select('*').eq('job_id',wr.job_id).order('created_at'),supabase.from('warehouse_receipt_parties').select('*').eq('warehouse_receipt_id',id),supabase.from('entities').select('*').eq('organization_id',wr.organization_id).order('name').limit(2500),supabase.from('documents').select('*').eq('warehouse_receipt_id',id).eq('is_current',true).order('created_at',{ascending:false}),supabase.from('operational_flags').select('*').eq('warehouse_receipt_id',id).eq('active',true).order('created_at',{ascending:false}),supabase.from('receiving_controls').select('*').eq('warehouse_receipt_id',id).order('created_at',{ascending:false}),supabase.from('workflow_definitions').select('*').eq('organization_id',wr.organization_id).eq('transaction_type','WAREHOUSE_RECEIPT').eq('is_active',true).order('version',{ascending:false}).limit(1),supabase.from('workflow_events').select('*').eq('warehouse_receipt_id',id).order('created_at'),supabase.from('warehouse_locations').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('code'),supabase.from('organization_unit_profiles').select('*').eq('organization_id',wr.organization_id).eq('is_default',true).maybeSingle(),supabase.from('organization_reference_options').select('*').eq('organization_id',wr.organization_id).eq('active',true).order('option_group').order('sort_order')];
 const [job,visit,cargo,parties,entities,docs,flags,controls,wf,events,locs,units,opts]=await Promise.all(q);const ids=(entities.data||[]).map(x=>x.id);let addresses=[],contacts=[];if(ids.length){const[a,c]=await Promise.all([supabase.from('entity_addresses').select('*').in('entity_id',ids).eq('active',true),supabase.from('entity_contacts').select('*').in('entity_id',ids).eq('active',true)]);addresses=a.data||[];contacts=c.data||[]}
 S={wr,job:job.data||{},visit:visit.data?.[0]||null,cargo:cargo.data||[],parties:parties.data||[],entities:entities.data||[],docs:docs.data||[],flags:flags.data||[],controls:controls.data||[],workflow:wf.data?.[0]||null,events:events.data||[],locations:locs.data||[],units:units.data||{weight_unit:'LB',dimension_unit:'IN',volume_unit:'CBM',default_quantity_uom:'PCS'},options:opts.data||[],addresses,contacts};return S}
async function refresh(){await load(wrId)}

function toolbar(){return `<div class="wr19-tools"><button class="wr19-tool" data-out="pdf">▧ <span>WR PDF</span></button><button class="wr19-tool" data-out="4x6">▱ <span>4×6</span></button><button class="wr19-tool" data-out="2x1">▱ <span>2×1</span></button><button class="wr19-tool" data-doc-scan>${docIcon}<span>Scan document</span></button><button class="wr19-tool" data-doc-upload>${docIcon}<span>Upload</span></button><button class="wr19-tool" data-share>${mailIcon}<span>Share</span></button></div>`}
function head(){const s=summary(),c=completion();return `<header class="wr19-head"><div class="wr19-headtop"><div><div class="wr19-k">Warehouse receipt</div><div class="wr19-num">${esc(S.wr.receipt_number)}</div><div class="wr19-sub">${esc(customerName())} · Created ${fmt(S.wr.created_at)}${S.wr.received_at?` · Received ${fmt(S.wr.received_at)}`:''}</div></div><span class="wr19-state">${esc(S.wr.status)}</span></div><div class="wr19-bar"><div class="wr19-mode"><button data-mode="guided" class="${mode==='guided'?'active':''}">Guided</button><button data-mode="record" class="${mode==='record'?'active':''}">Record</button></div>${toolbar()}</div><div class="wr19-summary"><div class="wr19-stat"><small>Expected</small><b>${s.expected??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr19-stat"><small>Unloaded</small><b>${s.unloaded??'—'} ${S.visit?.unload_uom||''}</b></div><div class="wr19-stat"><small>Processed</small><b>${s.processed}</b></div><div class="wr19-stat"><small>Put away</small><b>${s.putaway}</b></div><div class="wr19-stat"><small>Exceptions</small><b>${s.exceptions}</b></div><div class="wr19-stat"><small>Missing</small><b>${s.missing}</b></div></div><div class="wr19-meter"><span style="width:${c.pct}%"></span></div></header>`}
function timeline(){const v=S.visit||{};return `<div class="wr19-timeline">${[['Checked in',v.time_in],['ID verified',v.driver_id_verified_at],['Unload started',v.operation_started_at],['Unload finished',v.operation_completed_at],['Released',v.time_out]].map(([l,t])=>`<div class="wr19-event ${t?'done':''}"><small>${l}</small><b>${t?'✓ '+tm(t):'Pending'}</b></div>`).join('')}</div>`}
function progress(){const c=current();return `<div class="wr19-progress">${steps().map(x=>`<span class="${done(x)?'done':x.key===c?.key?'now':''}">${done(x)?'✓ ':''}${esc(x.label)}${x.required===false?' · optional':''}</span>`).join('')}</div>`}
function smartField(id,label,value='',role=''){return `<label class="wr19-field wr19-smart"><span>${esc(label)}</span><input id="${id}" data-smart="${esc(role)}" value="${esc(value)}" autocomplete="off" placeholder="Search, use once, or create new"><div class="wr19-smartmenu" hidden></div></label>`}
function selectedPartyCard(role,id){const p=role==='customer'?ent(S.job?.customer_id):ent(party(role)?.entity_id),name=role==='customer'?customerName():(party(role)?.display_name||p?.name||'Not selected');if(!p)return `<div class="wr19-party"><small>${esc(role)}</small><h4>${esc(name)}</h4><div class="wr19-partyaddress">Typed for this WR only.</div></div>`;const ads=S.addresses.filter(x=>x.entity_id===p.id),a=ads.find(x=>x.is_primary)||ads[0],cs=S.contacts.filter(x=>x.entity_id===p.id),c=cs.find(x=>x.is_primary)||cs[0];const addr=a?[a.line1,a.line2,[a.city,a.state_region,a.postal_code].filter(Boolean).join(' '),a.country_code].filter(Boolean).join('<br>'):'No saved address';return `<div class="wr19-party"><small>${esc(role)}</small><h4>${esc(p.name)}</h4><div class="wr19-partyaddress">${addr}</div><div class="wr19-contact">${esc(c?.name||'No primary contact')}${c?.phone?` · ${esc(c.phone)}`:''}${c?.email?`<br>${esc(c.email)}`:''}</div></div>`}

function guided(){const s=current(),i=steps().findIndex(x=>x.key===s.key);return `<section class="wr19-guide wr19-panel">${progress()}<div class="wr19-now">RIGHT NOW · ${i+1} OF ${steps().length}</div><h1 class="wr19-title">${esc(s.label)}</h1><div class="wr19-copy">${esc(s.description||copy(s.key))}</div>${timeline()}${guidedTask(s)}</section>`}
function copy(k){return({check_in:'Capture only what is needed to establish the dock visit.',verify_driver:'Capture the driver ID and record the verification statement.',start_unload:'Start the physical unload when custody transfer begins.',finish_unload:'Record the physical tally; detailed receiving may continue after release.',release_driver:'Close the dock visit and release the truck.',parties:'Confirm Customer, Shipper and Consignee. Master addresses and contacts follow the selected records.',receive_cargo:'Build the physical cargo hierarchy and process it quickly.',documents:'Capture and organize receiving documents.',compliance:'Review DG, in-bond / 7512 and FTZ controls only when applicable.',putaway:'Assign or scan destination locations.',complete:'Review missing requirements and close the WR.',notify_customer:'Send or record the customer notification.'}[k]||'Complete this step.')}
function guidedTask(s){const v=S.visit||{};switch(s.key){case'check_in':return `<div class="wr19-task"><h3>Who just arrived?</h3><div class="wr19-fields">${smartField('g-carrier','Carrier',v.carrier_name_snapshot||'','carrier')}<label class="wr19-field"><span>Driver</span><input id="g-driver" value="${esc(v.driver_name||'')}" placeholder="Driver name"></label><label class="wr19-field"><span>Reference</span><input id="g-ref" value="${esc(v.bol_number||v.pro_number||v.tracking_number||'')}" placeholder="BOL / PRO / tracking"></label><label class="wr19-field"><span>Door</span><input id="g-door" value="${esc(v.door||'')}" placeholder="Optional"></label></div><div class="wr19-actions"><button class="wr19-primary" data-g-checkin>Check in</button><button class="wr19-secondary wr19-mini-scan" data-scan-ref>${scanIcon} Scan code</button></div></div>`;case'verify_driver':return `<div class="wr19-task"><h3>Identity verification</h3><div class="wr19-actions"><button class="wr19-secondary" data-doc-scan>${docIcon} Scan / capture ID</button></div><label class="wr19-check"><input id="g-verify" type="checkbox"> I verified a government-issued photo ID and confirmed it matches the driver presenting the freight.</label><div class="wr19-actions"><button class="wr19-primary" data-g-verify>Confirm verification</button></div></div>`;case'start_unload':return `<div class="wr19-task"><h3>Ready to unload</h3><div class="wr19-actions"><button class="wr19-primary" data-g-start>Start unloading</button></div></div>`;case'finish_unload':return `<div class="wr19-task"><h3>Unload & tally</h3><div class="wr19-fields"><label class="wr19-field"><span>Expected</span><input id="g-exp" type="number" value="${esc(v.unload_expected_qty??'')}"></label><label class="wr19-field"><span>Actual unloaded</span><input id="g-act" type="number" value="${esc(v.unload_actual_qty??'')}"></label><label class="wr19-field"><span>UOM</span><input id="g-uom" value="${esc(v.unload_uom||'PLT')}"></label></div><div class="wr19-actions"><button class="wr19-primary" data-g-finish>Finish unloading</button></div></div>`;case'release_driver':return `<div class="wr19-task"><h3>Release driver</h3><div class="wr19-actions"><button class="wr19-primary" data-g-release>Release driver</button></div></div>`;case'parties':return `<div class="wr19-task"><h3>Parties</h3><div class="wr19-fields">${smartField('g-customer','Customer',customerName()==='Unidentified customer'?'':customerName(),'customer')}${smartField('g-shipper','Shipper',party('shipper')?.display_name||'','shipper')}${smartField('g-consignee','Consignee',party('consignee')?.display_name||'','consignee')}</div><div class="wr19-partygrid" style="margin-top:12px">${selectedPartyCard('customer')}${selectedPartyCard('shipper')}${selectedPartyCard('consignee')}</div><div class="wr19-actions"><button class="wr19-primary" data-g-parties>Save & continue</button></div></div>`;case'receive_cargo':return `<div class="wr19-task">${cargoView(true)}</div>`;case'documents':return `<div class="wr19-task">${documentsView(true)}${s.required===false?'<div class="wr19-actions"><button class="wr19-secondary" data-skip="documents">Skip optional step</button></div>':''}</div>`;case'compliance':return `<div class="wr19-task">${complianceView()}${s.required===false?'<div class="wr19-actions"><button class="wr19-secondary" data-skip="compliance">Not applicable / continue</button></div>':''}</div>`;case'putaway':return `<div class="wr19-task"><h3>Put away</h3>${putawayView()}</div>`;case'complete':return `<div class="wr19-task"><h3>Review & complete</h3>${missing().length?`<div class="wr19-card">Missing · ${esc(missing().join(' · '))}</div>`:'<div class="wr19-card">✓ Ready to complete</div>'}<div class="wr19-actions"><button class="wr19-primary" data-g-complete>Complete WR</button></div></div>`;case'notify_customer':return `<div class="wr19-task"><h3>Notify customer</h3><p>Share the WR PDF or record that the customer was notified.</p><div class="wr19-actions"><button class="wr19-primary" data-share>Share WR</button><button class="wr19-secondary" data-g-notify>Mark notified</button>${s.required===false?'<button class="wr19-secondary" data-skip="notify_customer">Skip</button>':''}</div></div>`;default:return `<div class="wr19-task"><h3>${esc(s.label)}</h3>${renderConfiguredActions(s)}<div class="wr19-actions"><button class="wr19-primary" data-g-generic="${esc(s.key)}">Mark complete</button></div></div>`}}
function renderConfiguredActions(s){return (s.actions||[]).length?`<div class="wr19-actions">${s.actions.map(a=>`<button class="wr19-secondary" data-config-action="${esc(a.type)}" data-target="${esc(a.target||'')}">${esc(a.label||a.type)}</button>`).join('')}</div>`:''}

const tabs=[['overview','Overview'],['parties','Parties'],['arrival','Arrival'],['cargo','Cargo'],['documents','Documents'],['compliance','Compliance'],['exceptions','Exceptions'],['activity','Activity']];
function record(){return `<nav class="wr19-tabs">${tabs.map(([k,l])=>`<button data-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</nav><section class="wr19-panel">${recordTab()}</section>`}
function recordTab(){return tab==='overview'?overview():tab==='parties'?partiesView():tab==='arrival'?arrivalView():tab==='cargo'?cargoView(false):tab==='documents'?documentsView(false):tab==='compliance'?complianceView():tab==='exceptions'?exceptionsView():activityView()}
function overview(){return `<div class="wr19-grid"><div class="wr19-card"><h3>Warehouse Receipt</h3><div class="wr19-fields"><label class="wr19-field"><span>WR number</span><input value="${esc(S.wr.receipt_number)}" readonly></label><label class="wr19-field"><span>Status</span><input value="${esc(S.wr.status)}" readonly></label><label class="wr19-field"><span>Created</span><input value="${esc(fmt(S.wr.created_at))}" readonly></label><label class="wr19-field"><span>Received</span><input value="${esc(fmt(S.wr.received_at))}" readonly></label></div><div class="wr19-partygrid" style="margin-top:12px">${selectedPartyCard('customer')}${selectedPartyCard('shipper')}${selectedPartyCard('consignee')}</div></div><div class="wr19-card"><h3>Readiness</h3><p>${missing().length?'Items still need attention.':'No blocking items detected.'}</p>${missing().map(x=>`<div class="wr19-badge warn" style="margin:5px 5px 0 0;display:inline-block">${esc(x)}</div>`).join('')||'<div class="wr19-badge good">Ready</div>'}<div class="wr19-actions"><button class="wr19-secondary" data-workflow-edit>Edit workflow</button></div></div></div>`}
function partiesView(){return `<div class="wr19-line"><div><h2 style="margin:0">Parties</h2><p style="color:#8093a8">Selected master records bring their address and contact information into the WR and PDF.</p></div><button class="wr19-primary" data-edit-parties>Edit parties</button></div><div class="wr19-partygrid" style="margin-top:13px">${selectedPartyCard('customer')}${selectedPartyCard('shipper')}${selectedPartyCard('consignee')}</div>`}
function arrivalView(){const v=S.visit||{};return `<div class="wr19-card"><h3>Dock visit</h3>${timeline()}<div class="wr19-fields"><label class="wr19-field"><span>Carrier</span><input value="${esc(v.carrier_name_snapshot||'')}" readonly></label><label class="wr19-field"><span>Driver</span><input value="${esc(v.driver_name||'')}" readonly></label><label class="wr19-field"><span>BOL</span><input value="${esc(v.bol_number||'')}" readonly></label><label class="wr19-field"><span>PRO / tracking</span><input value="${esc(v.pro_number||v.tracking_number||'')}" readonly></label><label class="wr19-field"><span>Door</span><input value="${esc(v.door||'')}" readonly></label><label class="wr19-field"><span>Seal / trailer</span><input value="${esc([v.seal_number,v.trailer_number].filter(Boolean).join(' / '))}" readonly></label></div></div>`}
function flatCargo(){const out=[];const walk=(x,d=0)=>{out.push([x,d]);children(x.id).forEach(c=>walk(c,d+1))};roots().forEach(x=>walk(x));return out}
function cargoView(guided=false){const q=cargoQuery.trim().toLowerCase(),rows=flatCargo().filter(([x])=>!q||[x.handling_unit_code,x.package_type,x.description,x.sku,x.part_number,x.lot_number,x.serial_number].some(v=>String(v||'').toLowerCase().includes(q)));return `<div class="wr19-cargobar"><div><h3 style="margin:0">Physical cargo</h3><p style="margin:4px 0 0;color:#7f92a8;font-size:10px">Hierarchy stays visible while the table remains sortable and fast to scan.</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><input class="wr19-search" id="cargo-q" value="${esc(cargoQuery)}" placeholder="Search cargo, SKU, part…"><button class="wr19-primary" data-cargo-add>＋ Cargo</button></div></div>${rows.length?`<div class="wr19-tablewrap"><table class="wr19-table"><thead><tr><th>Cargo</th><th>Description / part</th><th>Qty</th><th>Weight</th><th>Dimensions</th><th>Location</th><th>Controls</th><th>Actions</th></tr></thead><tbody>${rows.map(([x,d])=>cargoRow(x,d)).join('')}</tbody></table></div>`:'<div class="wr19-empty">No cargo recorded yet. Add the outer handling unit first.</div>'}`}
function cargoRow(x,d){const loc=S.locations.find(l=>l.id===(x.current_location_id||x.warehouse_location_id)),photos=S.docs.filter(z=>z.cargo_unit_id===x.id&&String(z.category||'').toUpperCase()==='PHOTO').length,controls=S.controls.filter(z=>z.cargo_unit_id===x.id).map(z=>z.control_type).join(' · '),dims=x.length_in&&x.width_in&&x.height_in?`${x.length_in}×${x.width_in}×${x.height_in} in`:'—';return `<tr><td><span class="wr19-indent ${d?'child':''}">${d?'↳':'▾'} ${esc(x.handling_unit_code||'')} ${esc(x.package_type||'')}</span></td><td><b>${esc(x.description||'—')}</b><br><small>${esc(x.part_number||x.sku||'')}</small></td><td>${esc(x.quantity||0)} ${esc(x.uom||'')}</td><td>${x.weight_lb?`${Number(x.weight_lb).toFixed(1)} lb`:'—'}</td><td>${dims}</td><td>${esc(loc?.code||'—')}</td><td>${controls?`<span class="wr19-badge warn">${esc(controls)}</span>`:''}${photos?`<span class="wr19-badge">📷 ${photos}</span>`:''}</td><td><div class="wr19-rowactions"><button data-cargo-edit="${x.id}">Edit</button><button data-cargo-inside="${x.id}">+ Inside</button><button data-cargo-photo="${x.id}">Photo</button><button data-cargo-control="${x.id}">DG / Customs</button><button data-cargo-exception="${x.id}">Exception</button><button data-cargo-label="${x.id}">Label</button></div></td></tr>`}
function documentsView(){const groups={};for(const d of S.docs){const key=docGroup==='cargo'?(d.cargo_unit_id?S.cargo.find(x=>x.id===d.cargo_unit_id)?.handling_unit_code||'Cargo':'Receipt-level'):(d.category||d.document_type||'Other');(groups[key] ||= []).push(d)}return `<div class="wr19-docbar"><div><h3 style="margin:0">Documents</h3><p style="margin:4px 0 0;color:#7f92a8;font-size:10px">Structured by category or cargo association.</p></div><div style="display:flex;gap:7px"><select id="doc-group" class="wr19-search"><option value="category" ${docGroup==='category'?'selected':''}>By category</option><option value="cargo" ${docGroup==='cargo'?'selected':''}>By cargo</option></select><button class="wr19-secondary" data-doc-scan>Scan</button><button class="wr19-primary" data-doc-upload>Upload</button></div></div><div class="wr19-doccats">${Object.entries(groups).map(([k,ds])=>`<section class="wr19-docgroup"><h4>${esc(k)} · ${ds.length}</h4>${ds.map(docRow).join('')}</section>`).join('')||'<div class="wr19-empty">No documents yet. Scan or upload the first document.</div>'}</div>`}
function docRow(d){return `<div class="wr19-docrow"><div class="wr19-docicon">▤</div><div><b>${esc(d.display_name||d.file_name||d.document_type||'Document')}</b><small>${esc(d.document_type||'OTHER')} · ${fmt(d.created_at)}${d.extraction?` · OCR data available`:''}</small></div><div class="wr19-docactions"><button data-doc-preview="${d.id}">Preview</button><button data-doc-download="${d.id}">Download</button><button data-doc-share="${d.id}">Share</button></div></div>`}
function complianceView(){const types=['DG','IN_BOND_7512','FTZ'];return `<div class="wr19-line"><div><h2 style="margin:0">Compliance controls</h2><p style="color:#8093a8">Only activate controls that apply to this receipt or cargo.</p></div><button class="wr19-primary" data-control-add>＋ Add control</button></div><div class="wr19-controlgrid" style="margin-top:13px">${types.map(t=>{const a=S.controls.filter(x=>x.control_type===t);return `<div class="wr19-control"><div class="state">${a.length?(a.every(x=>x.verified)?'verified':'pending'):'not applicable'}</div><h4>${t==='IN_BOND_7512'?'In-bond / 7512':t}</h4><p>${a.length?`${a.length} control${a.length===1?'':'s'} · ${a.filter(x=>x.verified).length} verified`:'No active control.'}</p>${a.map(x=>`<div class="wr19-badge ${x.verified?'good':'warn'}">${esc(x.status||'pending')}</div>`).join('')}</div>`}).join('')}</div>`}
function exceptionsView(){return `<div class="wr19-line"><div><h2 style="margin:0">Exception ledger</h2><p style="color:#8093a8">Damage, shortage, overage, seal discrepancies, holds and other operational issues.</p></div><button class="wr19-primary" data-exception-add>＋ Exception</button></div><div class="wr19-doccats" style="margin-top:13px">${S.flags.map(f=>`<div class="wr19-docgroup"><div class="wr19-line"><div><span class="wr19-badge warn">${esc(f.flag_type)}</span><h4 style="margin:8px 0 0">${esc(f.notes||'No notes')}</h4><small style="color:#71869d">${fmt(f.created_at)} · ${esc(f.severity||'')}</small></div><button class="wr19-secondary" data-flag-clear="${f.id}">Resolve</button></div></div>`).join('')||'<div class="wr19-empty">No active exceptions.</div>'}</div>`}
function activityView(){return `<div class="wr19-doccats">${S.events.slice().reverse().map(e=>`<div class="wr19-docgroup"><b>${esc(e.event_type)}</b><small style="display:block;color:#71869d;margin-top:4px">${fmt(e.created_at)}</small></div>`).join('')||'<div class="wr19-empty">No workflow activity yet.</div>'}</div>`}
function putawayView(){return roots().map(x=>`<div class="wr19-card"><div class="wr19-line"><div><b>${esc(x.handling_unit_code||x.package_type)}</b><div style="color:#71869d;font-size:9px">${esc(x.description||'')}</div></div><button class="wr19-secondary" data-putaway="${x.id}">${x.current_location_id||x.warehouse_location_id?'Change location':'Assign location'}</button></div></div>`).join('')||'<div class="wr19-empty">Add cargo before put-away.</div>'}

function render(){document.body.classList.add('wr19-active');main.innerHTML=`<section class="wr19">${head()}${mode==='guided'?guided():record()}<input type="file" id="wr19-upload" hidden multiple></section>`;bind()}
async function rerender(){await refresh();render()}

function bindSmart(){main.querySelectorAll('[data-smart]').forEach(inp=>{const menu=inp.parentElement.querySelector('.wr19-smartmenu');const show=()=>{const q=inp.value.trim().toLowerCase();const rows=S.entities.filter(e=>!q||e.name.toLowerCase().includes(q)||String(e.code||'').toLowerCase().includes(q)).slice(0,7);menu.innerHTML=rows.map(e=>{const a=S.addresses.find(x=>x.entity_id===e.id&&x.is_primary)||S.addresses.find(x=>x.entity_id===e.id);return `<button data-smartpick="${e.id}"><b>${esc(e.name)}</b><small>${esc([a?.line1,a?.city,a?.state_region].filter(Boolean).join(' · ')||e.code||'Saved record')}</small></button>`}).join('')+`<button data-smart-new="${esc(inp.dataset.smart)}">＋ Create new record</button>`;menu.hidden=false;menu.querySelectorAll('[data-smartpick]').forEach(b=>b.onclick=()=>{inp.value=ent(b.dataset.smartpick)?.name||'';inp.dataset.entityId=b.dataset.smartpick;menu.hidden=true});menu.querySelector('[data-smart-new]')?.addEventListener('click',()=>{menu.hidden=true;entityModal(inp.dataset.smart,inp.value,created=>{inp.value=created.name;inp.dataset.entityId=created.id})})};inp.addEventListener('input',show);inp.addEventListener('focus',show);inp.addEventListener('blur',()=>setTimeout(()=>menu.hidden=true,180))})}
function bind(){main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()});main.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});bindSmart();main.querySelector('#cargo-q')?.addEventListener('input',e=>{cargoQuery=e.target.value;clearTimeout(e.target._t);e.target._t=setTimeout(render,180)});main.querySelector('#doc-group')?.addEventListener('change',e=>{docGroup=e.target.value;render()});
 main.querySelectorAll('[data-out]').forEach(b=>b.onclick=async()=>{try{if(b.dataset.out==='pdf')await window.NodaraWROutput?.warehouseReceiptPDF(wrId);if(b.dataset.out==='4x6')await window.NodaraWROutput?.labels4x6(wrId);if(b.dataset.out==='2x1')await window.NodaraWROutput?.labels2x1(wrId)}catch(e){alert(e.message)}});main.querySelectorAll('[data-doc-scan]').forEach(b=>b.onclick=()=>window.NodaraWRScanner?.open?.({category:'RECEIVING_DOCUMENT'}));main.querySelectorAll('[data-doc-upload]').forEach(b=>b.onclick=()=>main.querySelector('#wr19-upload')?.click());main.querySelector('#wr19-upload')?.addEventListener('change',uploadFiles);main.querySelectorAll('[data-share]').forEach(b=>b.onclick=shareWR);
 main.querySelector('[data-scan-ref]')?.addEventListener('click',()=>window.nodaraScanTask?.({title:'Scan BOL / PRO / tracking',hint:'Barcode · QR · BOL · PRO · AWB',onScan:async code=>{main.querySelector('#g-ref').value=code;return true}}));
 main.querySelector('[data-g-checkin]')?.addEventListener('click',checkin);main.querySelector('[data-g-verify]')?.addEventListener('click',verify);main.querySelector('[data-g-start]')?.addEventListener('click',()=>visitUpdate({operation_started_at:new Date().toISOString()},'Unload started'));main.querySelector('[data-g-finish]')?.addEventListener('click',finishUnload);main.querySelector('[data-g-release]')?.addEventListener('click',()=>visitUpdate({time_out:new Date().toISOString()},'Driver released'));main.querySelector('[data-g-parties]')?.addEventListener('click',saveParties);main.querySelector('[data-g-complete]')?.addEventListener('click',completeWR);main.querySelector('[data-g-notify]')?.addEventListener('click',async()=>{await addEvent('CUSTOMER_NOTIFIED');await rerender()});main.querySelectorAll('[data-skip]').forEach(b=>b.onclick=async()=>{await addEvent('STEP_SKIPPED',{step_key:b.dataset.skip});await rerender()});main.querySelectorAll('[data-g-generic]').forEach(b=>b.onclick=async()=>{await addEvent('STEP_COMPLETED',{step_key:b.dataset.gGeneric});await rerender()});
 main.querySelectorAll('[data-cargo-add]').forEach(b=>b.onclick=()=>cargoModal());main.querySelectorAll('[data-cargo-edit]').forEach(b=>b.onclick=()=>cargoModal(S.cargo.find(x=>x.id===b.dataset.cargoEdit)));main.querySelectorAll('[data-cargo-inside]').forEach(b=>b.onclick=()=>cargoModal(null,S.cargo.find(x=>x.id===b.dataset.cargoInside)));main.querySelectorAll('[data-cargo-photo]').forEach(b=>b.onclick=()=>window.NodaraWRMedia?.openCargoCamera?.({cargoId:b.dataset.cargoPhoto}));main.querySelectorAll('[data-cargo-control]').forEach(b=>b.onclick=()=>controlModal(b.dataset.cargoControl));main.querySelectorAll('[data-cargo-exception]').forEach(b=>b.onclick=()=>exceptionModal(b.dataset.cargoException));main.querySelectorAll('[data-cargo-label]').forEach(b=>b.onclick=()=>window.NodaraWROutput?.labels4x6(wrId,[b.dataset.cargoLabel]));main.querySelectorAll('[data-putaway]').forEach(b=>b.onclick=()=>putawayModal(b.dataset.putaway));main.querySelector('[data-control-add]')?.addEventListener('click',()=>controlModal());main.querySelector('[data-exception-add]')?.addEventListener('click',()=>exceptionModal());main.querySelectorAll('[data-flag-clear]').forEach(b=>b.onclick=async()=>{await supabase.from('operational_flags').update({active:false,cleared_at:new Date().toISOString(),cleared_by:await uid()}).eq('id',b.dataset.flagClear);await rerender()});main.querySelector('[data-edit-parties]')?.addEventListener('click',()=>{mode='guided';const st=steps().find(x=>x.key==='parties');if(st){S.events=S.events.filter(e=>!(e.event_type==='STEP_COMPLETED'&&e.event_data?.step_key==='parties'))}render()});main.querySelector('[data-workflow-edit]')?.addEventListener('click',()=>window.nodaraWorkflowStudio?.('WAREHOUSE_RECEIPT'));main.querySelectorAll('[data-config-action]').forEach(b=>b.onclick=()=>runConfiguredAction(b.dataset.configAction,b.dataset.target));
 main.querySelectorAll('[data-doc-preview],[data-doc-download],[data-doc-share]').forEach(b=>b.onclick=()=>documentAction(b));
}
async function checkin(){const carrier=main.querySelector('#g-carrier'),payload={carrier_name_snapshot:carrier?.value.trim()||null,carrier_id:carrier?.dataset.entityId||null,driver_name:main.querySelector('#g-driver')?.value.trim()||null,door:main.querySelector('#g-door')?.value.trim()||null,bol_number:main.querySelector('#g-ref')?.value.trim()||null,time_in:new Date().toISOString()};if(S.visit){await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id)}else{await supabase.from('warehouse_visits').insert({...payload,organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,direction:'inbound',created_by:await uid()})}toast('Checked in ✓');await rerender()}
async function visitUpdate(payload,msg){if(!S.visit)return alert('Check in first.');await supabase.from('warehouse_visits').update(payload).eq('id',S.visit.id);toast(msg+' ✓');await rerender()}
async function verify(){if(!main.querySelector('#g-verify')?.checked)return alert('Confirm the verification statement.');await visitUpdate({driver_id_verified:true,driver_id_verified_at:new Date().toISOString(),driver_id_verified_by:await uid()},'ID verified')}
async function finishUnload(){await visitUpdate({unload_expected_qty:Number(main.querySelector('#g-exp')?.value||0)||null,unload_actual_qty:Number(main.querySelector('#g-act')?.value||0)||null,unload_uom:main.querySelector('#g-uom')?.value||'PLT',operation_completed_at:new Date().toISOString()},'Unload finished')}
async function saveParties(){const roles=[['customer','g-customer'],['shipper','g-shipper'],['consignee','g-consignee']];for(const[r,id]of roles){const inp=main.querySelector('#'+id),name=inp?.value.trim();if(!name)continue;let e=inp.dataset.entityId?ent(inp.dataset.entityId):S.entities.find(x=>x.name.toLowerCase()===name.toLowerCase());if(r==='customer'){if(e)await supabase.from('jobs').update({customer_id:e.id}).eq('id',S.wr.job_id);else await supabase.from('jobs').update({description:S.job.description}).eq('id',S.wr.job_id)}else{await supabase.from('warehouse_receipt_parties').delete().eq('warehouse_receipt_id',wrId).eq('role',r);await supabase.from('warehouse_receipt_parties').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,role:r,entity_id:e?.id||null,display_name:name,phone:e?.phone||null,email:e?.email||null})}}await supabase.from('warehouse_receipts').update({identification_status:'identified'}).eq('id',wrId);toast('Parties saved ✓');await rerender()}
async function completeWR(){if(missing().filter(x=>!['Driver on site'].includes(x)).length)return alert('Complete the required items first: '+missing().join(', '));await supabase.from('warehouse_receipts').update({status:'completed',completed_at:new Date().toISOString(),received_at:S.wr.received_at||new Date().toISOString(),processing_status:'completed'}).eq('id',wrId);await addEvent('STEP_COMPLETED',{step_key:'complete'});await rerender()}

function modal(html){const back=document.createElement('div'),box=document.createElement('div');back.className='wr19-modalback';box.className='wr19-modal';box.innerHTML=html;document.body.append(back,box);const close=()=>{back.remove();box.remove()};back.onclick=close;box.querySelector('[data-x]')?.addEventListener('click',close);return{box,close}}
function entityModal(role,name='',cb=()=>{}){const m=modal(`<div class="wr19-modalhead"><div><div class="wr19-k">QUICK CREATE</div><h3>New ${esc(role)} record</h3></div><button class="wr19-x" data-x>×</button></div><div class="wr19-fields"><label class="wr19-field"><span>Name</span><input id="qe-name" value="${esc(name)}"></label><label class="wr19-field"><span>Code</span><input id="qe-code"></label><label class="wr19-field"><span>Address</span><input id="qe-line1"></label><label class="wr19-field"><span>City</span><input id="qe-city"></label><label class="wr19-field"><span>State / region</span><input id="qe-state"></label><label class="wr19-field"><span>Postal code</span><input id="qe-postal"></label><label class="wr19-field"><span>Contact name</span><input id="qe-contact"></label><label class="wr19-field"><span>Email</span><input id="qe-email"></label><label class="wr19-field"><span>Phone</span><input id="qe-phone"></label></div><div class="wr19-actions"><button class="wr19-primary" id="qe-save">Create & select</button></div>`);m.box.querySelector('#qe-save').onclick=async()=>{const n=m.box.querySelector('#qe-name').value.trim();if(!n)return;const{data:e,error}=await supabase.from('entities').insert({organization_id:S.wr.organization_id,name:n,code:m.box.querySelector('#qe-code').value.trim()||null,roles:[role.toUpperCase()],email:m.box.querySelector('#qe-email').value.trim()||null,phone:m.box.querySelector('#qe-phone').value.trim()||null}).select().single();if(error)return alert(error.message);const line=m.box.querySelector('#qe-line1').value.trim();if(line)await supabase.from('entity_addresses').insert({organization_id:S.wr.organization_id,entity_id:e.id,address_type:'MAIN',line1:line,city:m.box.querySelector('#qe-city').value.trim()||null,state_region:m.box.querySelector('#qe-state').value.trim()||null,postal_code:m.box.querySelector('#qe-postal').value.trim()||null,is_primary:true,active:true});const cn=m.box.querySelector('#qe-contact').value.trim();if(cn)await supabase.from('entity_contacts').insert({organization_id:S.wr.organization_id,entity_id:e.id,name:cn,email:m.box.querySelector('#qe-email').value.trim()||null,phone:m.box.querySelector('#qe-phone').value.trim()||null,is_primary:true,active:true});S.entities.push(e);cb(e);m.close();toast('Record created ✓')}}
function cargoModal(x=null,parent=null){const weightUnit=S.units?.weight_unit||'LB',dimUnit=S.units?.dimension_unit||'IN',types=packageTypes();const m=modal(`<div class="wr19-modalhead"><div><div class="wr19-k">CARGO</div><h3>${x?'Edit cargo':parent?'Add inside '+esc(parent.handling_unit_code||parent.package_type):'Add handling unit'}</h3></div><button class="wr19-x" data-x>×</button></div><div class="wr19-compactgrid"><div class="wr19-pillinput"><input id="c-qty" type="number" value="${esc(x?.quantity||1)}"></div><label class="wr19-field"><span>Package type</span><select id="c-type">${types.map(([t])=>`<option ${t===(x?.package_type||'PALLET')?'selected':''}>${t}</option>`).join('')}<option value="__NEW__">＋ Add type…</option></select></label><label class="wr19-field"><span>Description / SKU / Part</span><input id="c-desc" value="${esc(x?.description||'')}" placeholder="Description"></label></div><div class="wr19-fields"><label class="wr19-field"><span>Part number</span><input id="c-part" value="${esc(x?.part_number||'')}"></label><label class="wr19-field"><span>SKU</span><input id="c-sku" value="${esc(x?.sku||'')}"></label><label class="wr19-field"><span>Lot</span><input id="c-lot" value="${esc(x?.lot_number||'')}"></label><label class="wr19-field"><span>Serial</span><input id="c-serial" value="${esc(x?.serial_number||'')}"></label></div><div class="wr19-fields"><label class="wr19-field"><span>Gross weight</span><div class="wr19-pillinput"><input id="c-weight" type="number" step="any" value="${esc(x?.weight_lb||'')}"><select id="c-wu"><option>LB</option><option ${weightUnit==='KG'?'selected':''}>KG</option></select></div></label><label class="wr19-field"><span>Dimensions</span><div class="wr19-pillinput"><input id="c-l" type="number" placeholder="L" value="${esc(x?.length_in||'')}"><input id="c-w" type="number" placeholder="W" value="${esc(x?.width_in||'')}"><input id="c-h" type="number" placeholder="H" value="${esc(x?.height_in||'')}"><select id="c-du"><option>IN</option><option ${dimUnit==='CM'?'selected':''}>CM</option></select></div></label></div><div class="wr19-metrics"><div class="wr19-metric"><small>UOM</small><b id="c-uom">—</b></div><div class="wr19-metric"><small>Volume</small><b id="c-vol">—</b></div><div class="wr19-metric"><small>Chargeable</small><b id="c-chg">—</b></div></div><div class="wr19-actions"><button class="wr19-secondary" id="c-photo">${cameraIcon} Photos</button><button class="wr19-secondary" id="c-control">DG / Customs</button><button class="wr19-secondary" id="c-exception">Exception</button><button class="wr19-primary" id="c-save">${x?'Save changes':'Add cargo'}</button></div>`);const type=m.box.querySelector('#c-type');const calc=()=>{const t=type.value,pu=packageTypes().find(z=>z[0]===t);m.box.querySelector('#c-uom').textContent=pu?.[1]||t;let l=+m.box.querySelector('#c-l').value,w=+m.box.querySelector('#c-w').value,h=+m.box.querySelector('#c-h').value;if(m.box.querySelector('#c-du').value==='CM'){l/=2.54;w/=2.54;h/=2.54}const cbm=l*w*h*0.000016387064;m.box.querySelector('#c-vol').textContent=l&&w&&h?cbm.toFixed(3)+' m³':'—';m.box.querySelector('#c-chg').textContent=l&&w&&h?(l*w*h/166).toFixed(1)+' lb':'—'};m.box.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',calc));type.onchange=()=>{if(type.value==='__NEW__')return packageTypeModal(created=>{const o=document.createElement('option');o.value=created.code;o.textContent=created.label;type.insertBefore(o,type.lastElementChild);type.value=created.code;calc()});calc()};calc();m.box.querySelector('#c-photo').onclick=()=>x?window.NodaraWRMedia?.openCargoCamera?.({cargoId:x.id}):alert('Save the cargo first, then add photos.');m.box.querySelector('#c-control').onclick=()=>x?controlModal(x.id):alert('Save cargo first.');m.box.querySelector('#c-exception').onclick=()=>x?exceptionModal(x.id):alert('Save cargo first.');m.box.querySelector('#c-save').onclick=async()=>{let wt=+m.box.querySelector('#c-weight').value||null;if(wt&&m.box.querySelector('#c-wu').value==='KG')wt*=2.2046226218;let l=+m.box.querySelector('#c-l').value||null,w=+m.box.querySelector('#c-w').value||null,h=+m.box.querySelector('#c-h').value||null;if(m.box.querySelector('#c-du').value==='CM'){l=l/2.54;w=w/2.54;h=h/2.54}const t=type.value,pu=packageTypes().find(z=>z[0]===t);const p={organization_id:S.wr.organization_id,job_id:S.wr.job_id,parent_id:x?.parent_id||parent?.id||null,package_type:t,quantity:+m.box.querySelector('#c-qty').value||1,uom:pu?.[1]||t,description:m.box.querySelector('#c-desc').value.trim()||null,part_number:m.box.querySelector('#c-part').value.trim()||null,sku:m.box.querySelector('#c-sku').value.trim()||null,lot_number:m.box.querySelector('#c-lot').value.trim()||null,serial_number:m.box.querySelector('#c-serial').value.trim()||null,weight_lb:wt,length_in:l,width_in:w,height_in:h,processing_status:'processed',status:'received',metadata:{input_weight_unit:m.box.querySelector('#c-wu').value,input_dimension_unit:m.box.querySelector('#c-du').value}};let e;if(x)e=(await supabase.from('cargo_units').update(p).eq('id',x.id)).error;else e=(await supabase.from('cargo_units').insert(p)).error;if(e)return alert(e.message);m.close();toast('Cargo saved ✓');await rerender()}}
function packageTypeModal(cb){const m=modal(`<div class="wr19-modalhead"><h3>New package type</h3><button class="wr19-x" data-x>×</button></div><div class="wr19-fields"><label class="wr19-field"><span>Name / code</span><input id="pt-code" placeholder="BUNDLE"></label><label class="wr19-field"><span>Default UOM</span><input id="pt-uom" placeholder="BDL"></label></div><div class="wr19-actions"><button class="wr19-primary" id="pt-save">Add package type</button></div>`);m.box.querySelector('#pt-save').onclick=async()=>{const code=m.box.querySelector('#pt-code').value.trim().toUpperCase(),uom=m.box.querySelector('#pt-uom').value.trim().toUpperCase();if(!code)return;const{data,error}=await supabase.from('organization_reference_options').insert({organization_id:S.wr.organization_id,option_group:'PACKAGE_TYPE',code,label:code,uom:uom||code,active:true}).select().single();if(error)return alert(error.message);S.options.push(data);cb(data);m.close()}}
function controlModal(cargoId=null){const m=modal(`<div class="wr19-modalhead"><h3>Add compliance control</h3><button class="wr19-x" data-x>×</button></div><div class="wr19-fields"><label class="wr19-field"><span>Control</span><select id="ct-type"><option value="DG">Dangerous Goods</option><option value="IN_BOND_7512">In-bond / 7512</option><option value="FTZ">FTZ</option></select></label><label class="wr19-field"><span>Status</span><select id="ct-status"><option>pending</option><option>verified</option><option>hold</option><option>released</option></select></label><label class="wr19-field"><span>Reference / UN / bond</span><input id="ct-ref"></label><label class="wr19-field"><span>Class / type / status detail</span><input id="ct-detail"></label></div><div class="wr19-actions"><button class="wr19-primary" id="ct-save">Add control</button></div>`);m.box.querySelector('#ct-save').onclick=async()=>{const status=m.box.querySelector('#ct-status').value;const{error}=await supabase.from('receiving_controls').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,control_type:m.box.querySelector('#ct-type').value,status,verified:status==='verified'||status==='released',verified_at:status==='verified'||status==='released'?new Date().toISOString():null,verified_by:status==='verified'||status==='released'?await uid():null,details:{reference:m.box.querySelector('#ct-ref').value.trim(),detail:m.box.querySelector('#ct-detail').value.trim()}});if(error)return alert(error.message);m.close();await rerender()}}
function exceptionModal(cargoId=null){const m=modal(`<div class="wr19-modalhead"><h3>Add exception</h3><button class="wr19-x" data-x>×</button></div><div class="wr19-fields"><label class="wr19-field"><span>Type</span><select id="ex-type">${['DAMAGE','SHORTAGE','OVERAGE','WET','OPEN_PACKAGE','SEAL_DISCREPANCY','WRONG_CARGO','UNKNOWN_CARGO','MEASUREMENT_DISCREPANCY','HOLD','OTHER'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="wr19-field"><span>Severity</span><select id="ex-sev"><option>info</option><option selected>warning</option><option>critical</option></select></label><label class="wr19-field" style="grid-column:1/-1"><span>Notes</span><textarea id="ex-notes"></textarea></label></div><div class="wr19-actions"><button class="wr19-primary" id="ex-save">Create exception</button></div>`);m.box.querySelector('#ex-save').onclick=async()=>{const{error}=await supabase.from('operational_flags').insert({organization_id:S.wr.organization_id,warehouse_receipt_id:wrId,cargo_unit_id:cargoId,flag_type:m.box.querySelector('#ex-type').value,severity:m.box.querySelector('#ex-sev').value,active:true,source:'USER',notes:m.box.querySelector('#ex-notes').value.trim()||null,created_by:await uid()});if(error)return alert(error.message);m.close();await rerender()}}
function putawayModal(id){const x=S.cargo.find(z=>z.id===id);const m=modal(`<div class="wr19-modalhead"><h3>Put away ${esc(x?.handling_unit_code||x?.package_type||'cargo')}</h3><button class="wr19-x" data-x>×</button></div><div class="wr19-actions"><button class="wr19-secondary" id="pa-scan">${scanIcon} Scan location</button></div><label class="wr19-field"><span>Location</span><select id="pa-loc">${S.locations.map(l=>`<option value="${l.id}">${esc(l.code)} · ${esc(l.name||'')}</option>`).join('')}</select></label><div class="wr19-actions"><button class="wr19-primary" id="pa-save">Assign location</button></div>`);m.box.querySelector('#pa-scan').onclick=()=>window.nodaraScanTask?.({title:'Scan destination location',onScan:async code=>{const l=S.locations.find(z=>z.code===code);if(!l)return false;m.box.querySelector('#pa-loc').value=l.id;return true}});m.box.querySelector('#pa-save').onclick=async()=>{const loc=m.box.querySelector('#pa-loc').value;await supabase.from('cargo_units').update({current_location_id:loc,warehouse_location_id:loc}).eq('id',id);m.close();await rerender()}}
async function uploadFiles(e){for(const f of e.target.files||[]){const{data:tx}=await supabase.from('transactions').select('id').eq('transaction_type','WAREHOUSE_RECEIPT').eq('domain_record_id',wrId).maybeSingle();if(!tx?.id)return alert('WR transaction is missing.');const path=`${S.wr.organization_id}/${tx.id}/transaction/${crypto.randomUUID()}_${f.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;const up=await supabase.storage.from('nodara-documents').upload(path,f,{contentType:f.type,upsert:false});if(up.error)return alert(up.error.message);const reg=await supabase.rpc('nodara_register_document',{p_transaction_id:tx.id,p_document_type:'OTHER',p_storage_path:path,p_file_name:f.name,p_mime_type:f.type,p_cargo_object_id:null,p_entity_id:null,p_template_id:null,p_display_name:f.name,p_document_number:null,p_category:'RECEIVING',p_link_role:'SUPPORTING',p_source:'USER',p_status:'ACTIVE',p_notes:null,p_metadata:{uploaded_from:'WR_V19'},p_provenance:{source_type:'USER',surface:'WR_V19'}});if(reg.error)return alert(reg.error.message)}e.target.value='';await rerender()}
async function documentAction(b){const id=b.dataset.docPreview||b.dataset.docDownload||b.dataset.docShare,d=S.docs.find(x=>x.id===id);if(!d)return;const{data}=await supabase.storage.from('nodara-documents').createSignedUrl(d.storage_path,120);if(!data?.signedUrl)return alert('Could not open document.');if(b.dataset.docShare&&navigator.share){try{await navigator.share({title:d.display_name||d.file_name,url:data.signedUrl})}catch{};return}window.open(data.signedUrl,'_blank')}
async function shareWR(){const subj=encodeURIComponent(`${S.wr.receipt_number} · Warehouse Receipt`),body=encodeURIComponent(`Warehouse Receipt ${S.wr.receipt_number}\nCustomer: ${customerName()}\nShipper: ${party('shipper')?.display_name||'—'}\nConsignee: ${party('consignee')?.display_name||'—'}\n\nPlease find the Warehouse Receipt attached/exported from NODARA.`);location.href=`mailto:?subject=${subj}&body=${body}`}
function runConfiguredAction(type,target){if(type==='CAPTURE_CODE')return window.nodaraScanTask?.({title:target||'Scan code'});if(type==='SCAN_DOCUMENT')return window.NodaraWRScanner?.open?.({category:target||'RECEIVING_DOCUMENT'});if(type==='CAPTURE_PHOTO')return window.NodaraWRMedia?.openCargoCamera?.({allowUnassigned:false});if(type==='SIGNATURE')return alert('Signature action is configured for this step.');if(type==='PRINT_LABEL')return target==='2X1'?window.NodaraWROutput?.labels2x1(wrId):window.NodaraWROutput?.labels4x6(wrId);if(type==='GENERATE_DOCUMENT')return window.NodaraWROutput?.warehouseReceiptPDF(wrId);if(type==='ADD_CONTROL')return controlModal();if(type==='ADD_EXCEPTION')return exceptionModal();toast(`${type} ready`)}

export async function mountWarehouseReceiptV19(id,{view='guided'}={}){wrId=id;mode=view;await load(id);render();document.body.classList.remove('wr-canonical-loading');main.style.visibility='visible'}
export async function openNewReceivingV19(){document.body.classList.remove('wr19-active');window.nodaraSetActive?.('wr');main.style.visibility='visible';main.innerHTML=`<section class="wr19-arrival"><div class="wr19-arrivalhero"><div class="wr19-k">WAREHOUSE RECEIVING</div><h1>New receiving</h1><p>Scan what the driver gives you. NODARA can identify the reference before you type anything.</p></div><div class="wr19-scanarrival"><button class="wr19-scanbig" id="nr-scan">${scanIcon}<b>Scan arrival</b><small>Barcode · QR · BOL · PRO · AWB · shipping label</small></button><div class="wr19-startcard"><h3>Start manually</h3><div class="wr19-fields" style="grid-template-columns:1fr"><label class="wr19-field"><span>Reference type</span><select id="nr-type"><option>BOL</option><option>PRO</option><option>TRACKING</option><option>AWB</option><option>PO</option></select></label><label class="wr19-field"><span>Reference</span><input id="nr-ref" placeholder="Type or scan"></label></div><div class="wr19-actions"><button class="wr19-primary" id="nr-find">Find expected cargo</button><button class="wr19-secondary" id="nr-unidentified">Continue unidentified</button></div></div></div></section>`;const create=async()=>{const type=main.querySelector('#nr-type').value,ref=main.querySelector('#nr-ref').value.trim();const{data,error}=await supabase.rpc('create_warehouse_receipt_shell_v1',{p_reference_type:type,p_reference_value:ref||null,p_expected_source_type:null,p_expected_source_id:null,p_expected_snapshot:{source:'WR_V19'}});if(error)return alert(error.message);await mountWarehouseReceiptV19(data.warehouse_receipt_id,{view:'guided'})};main.querySelector('#nr-unidentified').onclick=create;main.querySelector('#nr-find').onclick=async()=>{const ref=main.querySelector('#nr-ref').value.trim();if(!ref)return alert('Scan or enter a reference first.');const{data}=await supabase.from('shipment_references').select('warehouse_receipt_id,reference_value').eq('reference_value',ref).limit(2);if(data?.length===1&&data[0].warehouse_receipt_id)return mountWarehouseReceiptV19(data[0].warehouse_receipt_id,{view:'guided'});await create()};main.querySelector('#nr-scan').onclick=()=>window.nodaraScanTask?.({title:'Scan arrival',hint:'Barcode · QR · BOL · PRO · AWB · shipping label',onScan:async code=>{main.querySelector('#nr-ref').value=code;return true}})}
window.nodaraOpenCanonicalWRV19=mountWarehouseReceiptV19;
window.nodaraNewCanonicalWRV19=openNewReceivingV19;
